import { test, expect } from '@playwright/test';

test.describe('Confirmation Modal Before Deletion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display confirmation modal with delete button when user attempts to delete a record', async ({ page }) => {
    // Locate and click the delete button using getByRole
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /confirm/i });
    await expect(confirmationModal).toBeVisible();

    // Verify modal has delete button using getByRole
    const confirmDeleteButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmDeleteButton).toBeVisible();

    // Verify delete button is enabled
    await expect(confirmDeleteButton).toBeEnabled();

    // Verify delete button has correct text
    await expect(confirmDeleteButton).toContainText('Delete Record');

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is enabled
    await expect(closeButton).toBeEnabled();

    // Verify modal has success message
    const successMessage = page.getByText(/record deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify success message is visible
    await expect(successMessage).toBeVisible();

    // Verify record is removed from list
    const recordList = page.getByRole('list');
    await expect(recordList).toContainText('Record Name');

    // Verify confirmation modal is closed
    await confirmationModal.evaluate((modal) => {
      modal.remove();
    });

    // Verify record is no longer in list
    await expect(recordList).not.toContainText('Record Name');
  });

  test('should prevent deletion when confirmation modal is closed without confirming', async ({ page }) => {
    // Locate and click the delete button using getByRole
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /confirm/i });
    await expect(confirmationModal).toBeVisible();

    // Verify delete button is visible
    const confirmDeleteButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmDeleteButton).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is enabled
    await expect(closeButton).toBeEnabled();

    // Click close button to dismiss modal
    await closeButton.click();

    // Verify confirmation modal is no longer visible
    await expect(confirmationModal).not.toBeVisible();

    // Verify record is still in list
    const recordList = page.getByRole('list');
    await expect(recordList).toContainText('Record Name');

    // Verify delete button is still enabled
    await expect(confirmDeleteButton).toBeEnabled();

    // Verify delete button still has correct text
    await expect(confirmDeleteButton).toContainText('Delete Record');
  });
});
